data = [int(x) for x in open("17-202.txt")]

def cond(x):
    return 100 <= x < 1000 and x % 10 == 5

count, ma = 0, 0
for i in range(2, len(data)):
    if (not cond(data[i - 2])) and cond(data[i - 1]) and (not cond(data[i])):
        count += 1
        ma = max(ma, sum(data[i - 2:i + 1]))
print(count, ma)

data = [int(x) for x in open("17-204.txt")]

def cond(x):
    return x > 0 and x % 10 == 9

count, ma = 0, -10 ** 9
for i in range(2, len(data)):
    if (not cond(data[i - 2])) and cond(data[i - 1]) and (not cond(data[i])):
        count += 1
        ma = max(ma, sum(data[i - 2:i + 1]))
print(count, ma)

data = [int(x) for x in open("17-271.txt")]
av = sum(data) / len(data)
count, max_s = 0, -10 ** 9
for i in range(len(data) - 1):
    a, b = data[i], data[i + 1]
    if abs(a) % 10 + abs(b) % 10 == 7:
        count += 1
        if a < av and b < av:
            max_s = max(max_s, a + b)
print(count, max_s)

data = [int(x) for x in open("17-278.txt")]

def to_base(n, base):
    s = ""
    n = abs(n)
    while n:
        s = str(n % base) + s
        n //= base
    return s

ref = 0
for x in data:
    if x % 32 == 0:
        ref += 3 * to_base(x, 5).count("3")

count, ma = 0, 0
for i in range(len(data) - 2):
    if data[i] > ref or data[i + 1] > ref or data[i + 2] > ref:
        count += 1
        ma = max(ma, data[i] + data[i + 1] + data[i + 2])
print(count, ma)

data = [int(x) for x in open("17-300.txt")]
max401 = max(x for x in data if x % 401 == 0)

def sum_digits(n):
    return sum(map(int, str(abs(n))))

def valid(a, b, c):
    return (
        a % (sum_digits(b) + sum_digits(c)) == 0
        or b % (sum_digits(a) + sum_digits(c)) == 0
        or c % (sum_digits(a) + sum_digits(b)) == 0
    )

count, mi = 0, None
for i in range(len(data) - 2):
    s = data[i] + data[i + 1] + data[i + 2]
    if valid(data[i], data[i + 1], data[i + 2]) and s > max401:
        count += 1
        mi = s if mi is None else min(mi, s)
print(count, mi)

data = [int(x) for x in open("17-340.txt")]
all22 = [x for x in data if x % 22 == 0]
m = sum(all22) / len(all22)

def valid(a, b):
    sa, sb = f"{a:o}", f"{b:o}"
    return (
        sa.index(max(sa)) < sa.index(min(sa))
        and sb.index(max(sb)) < sb.index(min(sb))
        and a + b < m
    )

count, ma = 0, 0
for i in range(len(data) - 1):
    if valid(data[i], data[i + 1]):
        count += 1
        ma = max(ma, data[i] + data[i + 1])
print(count, ma)

data = [int(x) for x in open("17-360.txt")]

def prod_digits(n):
    p = 1
    for ch in str(abs(n)):
        p *= int(ch)
    return p

max42 = max(x for x in data if prod_digits(x) % 100 == 42)
count, min_prod = 0, 10 ** 10
for a, b, c in zip(data, data[1:], data[2:]):
    if not all(x < max42 for x in (a, b, c)):
        continue
    opposites = [abs(x) ** 2 for x, y in ((a, b), (a, c), (b, c)) if x + y == 0]
    if opposites:
        count += 1
        min_prod = min(min_prod, min(opposites))
print(count, min_prod)
